// @options: {"timeout_ms":30000,"max_output_tokens":4000}
function unwrap(res) {
  if (res && res.isError) throw new Error("tool error");
  if (res && res.structuredContent !== undefined && res.structuredContent !== null) return res.structuredContent;
  const block = (res.content || []).find(b => b.type === "text");
  return JSON.parse(block.text);
}

const listRes = await tools.mcp__orders__list_orders({});
const list = unwrap(listRes);
const orders = list.orders || [];

const candidates = orders.filter(o =>
  o.paidHoursAgo > 72 && o.paymentStatus === "paid" && o.shipmentStatus === "pending"
);

const verified = await Promise.all(candidates.map(async (o) => {
  const [payRes, shipRes] = await Promise.all([
    tools.mcp__orders__get_payment({ orderId: o.orderId }),
    tools.mcp__orders__get_shipment({ orderId: o.orderId })
  ]);
  const pay = unwrap(payRes);
  const ship = unwrap(shipRes);
  const ok = pay.status === "paid" && ship.status === "pending";
  return { o, pay, ship, ok };
}));

const matched = verified.filter(v => v.ok).map(v => ({
  orderId: v.o.orderId,
  customer: v.o.customer,
  paidHoursAgo: v.o.paidHoursAgo,
  amount: v.o.amount,
  warehouse: v.ship.warehouse ?? v.o.warehouse,
  suggestion: `支付已等待${v.o.paidHoursAgo}小时仍未发货，请${v.ship.warehouse ?? v.o.warehouse}仓库优先安排出库并同步物流单号。`
}));

matched.sort((a, b) => b.paidHoursAgo - a.paidHoursAgo);

const report = { matchedCount: matched.length, top3: matched.slice(0, 3) };
text(JSON.stringify(report));

