{"code": "const list = await tools.mcp__orders__list_orders({});
const candidates = list.orders.filter(o =>
  o.paidHoursAgo > 72 && o.paymentStatus === "paid" && o.shipmentStatus === "pending"
);

const verified = await Promise.all(candidates.map(async (o) => {
  const [pay, ship] = await Promise.all([
    tools.mcp__orders__get_payment({ orderId: o.orderId }),
    tools.mcp__orders__get_shipment({ orderId: o.orderId }),
  ]);
  return { o, pay, ship };
}));

const matched = verified.filter(v => v.pay.status === "paid" && v.ship.status === "pending");

const top3 = matched
  .slice()
  .sort((a, b) => b.o.paidHoursAgo - a.o.paidHoursAgo)
  .slice(0, 3)
  .map(v => ({
    orderId: v.o.orderId,
    customer: v.o.customer,
    paidHoursAgo: v.o.paidHoursAgo,
    amount: v.o.amount,
    warehouse: v.ship.warehouse,
    suggestion: `支付已等待${v.o.paidHoursAgo}小时仍未发货，请${v.ship.warehouse}仓库优先安排出库并同步物流单号。`,
  }));

return { matchedCount: matched.length, top3 };", "description": "Filter and verify pending-shipment paid orders"}

